#!/bin/bash
set -e
wget -q https://services.gradle.org/distributions/gradle-8.2-bin.zip
unzip -oq gradle-8.2-bin.zip
export PATH="$PWD/gradle-8.2/bin:$PATH"
rm -rf app build.gradle settings.gradle gradle.properties
mkdir -p app/src/main/java/com/example/shtile app/src/main/res/drawable app/src/main/res/layout app/src/main/res/values app/src/main/assets
cp Gucci_core app/src/main/assets/ 2>/dev/null || true
cp Gucci_brutal app/src/main/assets/ 2>/dev/null || true

echo "pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }; dependencyResolutionManagement { repositories { google(); mavenCentral() } }; rootProject.name = 'Settings'; include ':app'" > settings.gradle
echo "plugins { id 'com.android.application' version '8.2.2' apply false; id 'org.jetbrains.kotlin.android' version '1.9.22' apply false }" > build.gradle
echo -e "android.useAndroidX=true\nandroid.nonTransitiveRClass=true\norg.gradle.jvmargs=-Xmx2048m" > gradle.properties
echo "plugins { id 'com.android.application'; id 'org.jetbrains.kotlin.android' }; android { namespace 'com.example.shtile'; compileSdk 34; defaultConfig { applicationId 'com.example.shtile'; minSdk 24; targetSdk 34; versionCode 99; versionName '99.0' }; compileOptions { sourceCompatibility JavaVersion.VERSION_17; targetCompatibility JavaVersion.VERSION_17 }; kotlinOptions { jvmTarget = '17' } }; dependencies { implementation 'androidx.appcompat:appcompat:1.6.1'; implementation 'androidx.core:core-ktx:1.12.0'; implementation 'com.google.android.material:material:1.11.0' }" > app/build.gradle
echo "<?xml version='1.0' encoding='utf-8'?><manifest xmlns:android='http://schemas.android.com/apk/res/android'><uses-permission android:name='android.permission.FOREGROUND_SERVICE'/><uses-permission android:name='android.permission.FOREGROUND_SERVICE_DATA_SYNC'/><application android:allowBackup='true' android:label='Settings' android:icon='@drawable/ic_app_icon' android:theme='@style/Theme.MaterialComponents.NoActionBar'><activity android:name='.MainActivity' android:exported='true'/><activity-alias android:name='.MainActivityAlias' android:targetActivity='.MainActivity' android:exported='true' android:enabled='true' android:icon='@drawable/ic_app_icon'><intent-filter><action android:name='android.intent.action.MAIN'/><category android:name='android.intent.category.LAUNCHER'/></intent-filter></activity-alias><receiver android:name='.FocusReceiver' android:exported='false'/><service android:name='.RunnerService' android:exported='false' android:foregroundServiceType='dataSync'/><service android:name='.SafeTileService' android:exported='true' android:icon='@drawable/ic_tile_normal' android:label='Boost' android:permission='android.permission.BIND_QUICK_SETTINGS_TILE'><intent-filter><action android:name='android.service.quicksettings.action.QS_TILE'/></intent-filter></service><service android:name='.BrutalTileService' android:exported='true' android:icon='@drawable/ic_tile_brutal' android:label='Turbo Mode' android:permission='android.permission.BIND_QUICK_SETTINGS_TILE'><intent-filter><action android:name='android.service.quicksettings.action.QS_TILE'/></intent-filter></service><service android:name='.FocusTileService' android:exported='true' android:icon='@drawable/ic_tile_focus' android:label='Focus Mode' android:permission='android.permission.BIND_QUICK_SETTINGS_TILE'><intent-filter><action android:name='android.service.quicksettings.action.QS_TILE'/></intent-filter></service></application></manifest>" > app/src/main/AndroidManifest.xml
echo "<?xml version='1.0' encoding='utf-8'?><resources><color name='bg_main'>#0B0F14</color><color name='bg_card'>#151B23</color><color name='accent_green'>#00E5A0</color><color name='text_primary'>#FFFFFF</color><color name='text_secondary'>#9BA3AF</color></resources>" > app/src/main/res/values/colors.xml
echo "<?xml version='1.0' encoding='utf-8'?><resources xmlns:tools='http://schemas.android.com/tools'><style name='Theme.MaterialComponents.NoActionBar' parent='Theme.MaterialComponents.NoActionBarBase'><item name='colorPrimary'>@color/accent_green</item><item name='colorSecondary'>@color/accent_green</item><item name='android:windowBackground'>@color/bg_main</item><item name='android:statusBarColor' tools:targetApi='l'>@color/bg_main</item><item name='android:navigationBarColor' tools:targetApi='l'>@color/bg_main</item><item name='materialAlertDialogTheme'>@style/CustomDialogTheme</item></style><style name='CustomDialogTheme' parent='ThemeOverlay.MaterialComponents.MaterialAlertDialog'><item name='colorPrimary'>@color/accent_green</item><item name='android:background'>@color/bg_card</item><item name='shapeAppearanceOverlay'>@style/ShapeAppearance.Custom</item></style><style name='ShapeAppearance.Custom' parent=''><item name='cornerFamily'>rounded</item><item name='cornerSize'>24dp</item></style></resources>" > app/src/main/res/values/themes.xml
echo "<ripple xmlns:android='http://schemas.android.com/apk/res/android' android:color='#33FFFFFF'><item><shape android:shape='rectangle'><solid android:color='@color/accent_green'/><corners android:radius='12dp'/></shape></item></ripple>" > app/src/main/res/drawable/bg_btn_save.xml
echo "<ripple xmlns:android='http://schemas.android.com/apk/res/android' android:color='#33FFFFFF'><item><shape android:shape='rectangle'><solid android:color='#232A35'/><stroke android:width='1dp' android:color='@color/accent_green'/><corners android:radius='22dp'/></shape></item></ripple>" > app/src/main/res/drawable/bg_btn_load.xml
echo "<vector xmlns:android='http://schemas.android.com/apk/res/android' android:width='108dp' android:height='108dp' android:viewportWidth='108' android:viewportHeight='108'><path android:fillColor='#0B0F14' android:pathData='M0,0h108v108h-108z'/><path android:fillColor='#00E5A0' android:pathData='M54,24C37.43,24 24,37.43 24,54C24,70.57 37.43,84 54,84C70.57,84 84,70.57 84,54C84,37.43 70.57,24 54,24ZM54,36C63.94,36 72,44.06 72,54C72,63.94 63.94,72 54,72C44.06,72 36,63.94 36,54C36,44.06 44.06,36 54,36ZM54,48C50.69,48 48,50.69 48,54C48,57.31 50.69,60 54,60C57.31,60 60,57.31 60,54C60,50.69 57.31,48 54,48Z'/></vector>" > app/src/main/res/drawable/ic_app_icon.xml
echo "<vector xmlns:android='http://schemas.android.com/apk/res/android' android:width='24dp' android:height='24dp' android:viewportWidth='24' android:viewportHeight='24'><path android:fillColor='#FFFFFFFF' android:pathData='M12,2c0,0-4,4-4,8v5h8v-5C16,6,12,2,12,2z M10,10a2,2 0 1,1 4,0a2,2 0 1,1 -4,0z M7,11v4l2,1v-5H7z M17,11v4l-2,1v-5H17z M11,17h2v5l-1-1l-1,1V17z'/></vector>" > app/src/main/res/drawable/ic_tile_normal.xml
echo "<vector xmlns:android='http://schemas.android.com/apk/res/android' android:width='24dp' android:height='24dp' android:viewportWidth='24' android:viewportHeight='24'><path android:fillColor='#FFFFFFFF' android:pathData='M7,2v11h3v9l7,-12h-4l4,-8z'/></vector>" > app/src/main/res/drawable/ic_tile_brutal.xml
echo "<vector xmlns:android='http://schemas.android.com/apk/res/android' android:width='24dp' android:height='24dp' android:viewportWidth='24' android:viewportHeight='24'><path android:fillColor='#FFFFFFFF' android:pathData='M12,8C9.79,8 8,9.79 8,12C8,14.21 9.79,16 12,16C14.21,16 16,14.21 16,12C16,9.79 14.21,8 12,8ZM12,14C10.9,14 10,13.1 10,12C10,10.9 10.9,10 12,10C13.1,10 14,10.9 14,12C14,13.1 13.1,14 12,14Z'/><path android:fillColor='#FFFFFFFF' android:pathData='M7.5,5.5C4.5,8.5 4.5,15.5 7.5,18.5L9,17C6.8,14.5 6.8,9.5 9,7L7.5,5.5Z'/><path android:fillColor='#FFFFFFFF' android:pathData='M16.5,5.5L15,7C17.2,9.5 17.2,14.5 15,17L16.5,18.5C19.5,15.5 19.5,8.5 16.5,5.5Z'/></vector>" > app/src/main/res/drawable/ic_tile_focus.xml
echo "<resources><string name='app_name'>Settings</string></resources>" > app/src/main/res/values/strings.xml
echo "<?xml version='1.0' encoding='utf-8'?><ScrollView xmlns:android='http://schemas.android.com/apk/res/android' xmlns:app='http://schemas.android.com/apk/res-auto' android:layout_width='match_parent' android:layout_height='match_parent' android:background='@color/bg_main' android:fillViewport='true'><LinearLayout android:orientation='vertical' android:padding='24dp' android:layout_width='match_parent' android:layout_height='wrap_content'><TextView android:id='@+id/titleText' android:text='INX-LOADER PANEL' android:textColor='@color/text_primary' android:textSize='32sp' android:textStyle='bold' android:layout_width='wrap_content' android:layout_height='wrap_content'/><TextView android:id='@+id/subtitleText' android:text='Invisible X Loader Owner- GUCCI' android:textColor='@color/text_secondary' android:textSize='14sp' android:layout_marginTop='4dp' android:layout_marginBottom='32dp' android:layout_width='wrap_content' android:layout_height='wrap_content'/><com.google.android.material.card.MaterialCardView android:layout_width='match_parent' android:layout_height='wrap_content' app:cardBackgroundColor='@color/bg_card' app:cardCornerRadius='16dp' app:strokeWidth='1dp' app:strokeColor='#232A35' android:layout_marginBottom='16dp'><LinearLayout android:orientation='vertical' android:padding='20dp' android:layout_width='match_parent' android:layout_height='wrap_content'><TextView android:text='LICENSE KEY' android:textColor='@color/accent_green' android:textSize='12sp' android:textStyle='bold' android:layout_marginBottom='8dp' android:layout_width='wrap_content' android:layout_height='wrap_content'/><EditText android:id='@+id/keyInput' android:hint='Enter key...' android:inputType='text' android:padding='12dp' android:background='#00000000' android:textColor='@color/text_primary' android:textColorHint='@color/text_secondary' android:layout_width='match_parent' android:layout_height='wrap_content'/></LinearLayout></com.google.android.material.card.MaterialCardView><com.google.android.material.card.MaterialCardView android:layout_width='match_parent' android:layout_height='wrap_content' app:cardBackgroundColor='@color/bg_card' app:cardCornerRadius='16dp' app:strokeWidth='1dp' app:strokeColor='#232A35' android:layout_marginBottom='32dp'><LinearLayout android:orientation='vertical' android:padding='20dp' android:layout_width='match_parent' android:layout_height='wrap_content'><TextView android:text='SELECT DRIVER (1-10)' android:textColor='@color/accent_green' android:textSize='12sp' android:textStyle='bold' android:layout_marginBottom='8dp' android:layout_width='wrap_content' android:layout_height='wrap_content'/><EditText android:id='@+id/brutalInput' android:hint='e.g. 7' android:inputType='number' android:padding='12dp' android:background='#00000000' android:textColor='@color/text_primary' android:textColorHint='@color/text_secondary' android:layout_width='match_parent' android:layout_height='wrap_content'/><TextView android:id='@+id/driverNameText' android:textColor='@color/accent_green' android:textSize='14sp' android:textStyle='bold' android:layout_marginTop='4dp' android:paddingStart='12dp' android:layout_width='wrap_content' android:layout_height='wrap_content'/></LinearLayout></com.google.android.material.card.MaterialCardView><Button android:id='@+id/saveKeyBtn' android:text='SAVE CONFIGURATION' android:textColor='#000000' android:textSize='14sp' android:textStyle='bold' android:background='@drawable/bg_btn_save' android:layout_width='match_parent' android:layout_height='56dp'/><Button android:id='@+id/loadFilesBtn' android:layout_width='wrap_content' android:layout_height='44dp' android:layout_marginTop='16dp' android:layout_gravity='center_horizontal' android:paddingStart='32dp' android:paddingEnd='32dp' android:text='LOAD INX' android:textColor='@color/accent_green' android:textSize='13sp' android:textStyle='bold' android:background='@drawable/bg_btn_load'/><TextView android:id='@+id/status' android:paddingTop='24dp' android:gravity='center' android:textColor='@color/text_secondary' android:textSize='12sp' android:layout_width='match_parent' android:layout_height='wrap_content'/><TextView android:id='@+id/contactAdminText' android:paddingTop='40dp' android:gravity='center' android:text='Contact Admin for Help' android:textColor='@color/accent_green' android:textSize='14sp' android:textStyle='bold' android:paddingBottom='20dp' android:layout_width='match_parent' android:layout_height='wrap_content'/></LinearLayout></ScrollView>" > app/src/main/res/layout/activity_main.xml
cat > app/src/main/java/com/example/shtile/Installer.kt << 'EOF'
package com.example.shtile; import android.content.Context; import android.os.Handler; import android.os.Looper; import java.io.File; object Installer { fun installAll(c: Context, d: ((Boolean) -> Unit)? = null) { Thread { var ok = true; for (n in listOf("Gucci_core", "Gucci_brutal")) { try { val b = c.assets.open(n).readBytes(); val f = File(c.cacheDir, n); f.writeBytes(b); val p = ProcessBuilder("su", "-c", "cp ${f.absolutePath} /data/local/tmp/$n && chmod 755 /data/local/tmp/$n").redirectErrorStream(true).start(); p.inputStream.bufferedReader().readText(); if (p.waitFor() != 0) ok = false; f.delete() } catch (e: Exception) { ok = false } }; Handler(Looper.getMainLooper()).post { d?.invoke(ok) } }.start() } }
EOF

cat > app/src/main/java/com/example/shtile/RunnerService.kt << 'EOF'
package com.example.shtile; import android.app.*; import android.content.Intent; import android.os.*; import android.widget.Toast; import androidx.core.app.NotificationCompat; class RunnerService : Service() { override fun onStartCommand(i: Intent?, f: Int, s: Int): Int { if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) { val nm = getSystemService(NOTIFICATION_SERVICE) as NotificationManager; if (nm.getNotificationChannel("c") == null) nm.createNotificationChannel(NotificationChannel("c", "c", NotificationManager.IMPORTANCE_MIN)) }; try { startForeground(1, NotificationCompat.Builder(this, "c").setSmallIcon(android.R.drawable.stat_notify_sync_noanim).build()) } catch (e: Exception) {}; val a = i?.action; Thread { try { val p = getSharedPreferences("GucciPrefs", MODE_PRIVATE); val c = if (a == "BRUTAL") "cd /data/local/tmp && (echo 2; sleep 5; echo ${p.getString("brutal_option", "7")}; sleep 2) | ./Gucci_brutal" else { val k = p.getString("license_key", "")?.trim(); if (k.isNullOrEmpty()) { Handler(Looper.getMainLooper()).post { Toast.makeText(applicationContext, "Save Key first!", Toast.LENGTH_LONG).show() }; stopSelf(); return@Thread }; "cd /data/local/tmp && (sleep 4; echo '$k'; sleep 2) | ./Gucci_core" }; val pr = ProcessBuilder("su", "-c", c).redirectErrorStream(true).start(); pr.inputStream.bufferedReader().readText(); pr.waitFor() } catch (e: Exception) {}; stopForeground(true); stopSelf() }.start(); return START_NOT_STICKY }; override fun onBind(i: Intent?): IBinder? = null }
EOF

cat > app/src/main/java/com/example/shtile/SafeTileService.kt << 'EOF'
package com.example.shtile; import android.content.Intent; import android.os.Build; import android.service.quicksettings.Tile; import android.service.quicksettings.TileService; class SafeTileService : TileService() { override fun onStartListening() { qsTile?.apply { label = "Boost"; state = Tile.STATE_INACTIVE; updateTile() } }; override fun onClick() { val i = Intent(this, RunnerService::class.java).apply { action = "NORMAL" }; if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) startForegroundService(i) else startService(i) } }
EOF

cat > app/src/main/java/com/example/shtile/BrutalTileService.kt << 'EOF'
package com.example.shtile; import android.content.Intent; import android.os.Build; import android.service.quicksettings.Tile; import android.service.quicksettings.TileService; class BrutalTileService : TileService() { override fun onStartListening() { qsTile?.apply { label = "Turbo Mode"; state = Tile.STATE_INACTIVE; updateTile() } }; override fun onClick() { val i = Intent(this, RunnerService::class.java).apply { action = "BRUTAL" }; if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) startForegroundService(i) else startService(i) } }
EOF

cat > app/src/main/java/com/example/shtile/FocusTileService.kt << 'EOF'
package com.example.shtile; import android.content.ComponentName; import android.content.Intent; import android.content.pm.PackageManager; import android.os.Handler; import android.os.Looper; import android.service.quicksettings.Tile; import android.service.quicksettings.TileService; class FocusTileService : TileService() { override fun onStartListening() { update() }; override fun onClick() { sendBroadcast(Intent(this, FocusReceiver::class.java).apply { action = "com.example.shtile.TOGGLE_FOCUS" }); Handler(Looper.getMainLooper()).postDelayed({ update() }, 1000) }; private fun update() { val a = ComponentName(packageName, "${packageName}.MainActivityAlias"); val s = packageManager.getComponentEnabledSetting(a); qsTile?.apply { label = "Focus Mode"; state = if (s == PackageManager.COMPONENT_ENABLED_STATE_DISABLED) Tile.STATE_ACTIVE else Tile.STATE_INACTIVE; updateTile() } } }
EOF

cat > app/src/main/java/com/example/shtile/FocusReceiver.kt << 'EOF'
package com.example.shtile; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.content.ComponentName; import android.content.pm.PackageManager; class FocusReceiver : BroadcastReceiver() { override fun onReceive(c: Context, i: Intent) { if (i.action == "com.example.shtile.TOGGLE_FOCUS") { Thread { try { val a = ComponentName(c.packageName, "${c.packageName}.MainActivityAlias"); val h = c.packageManager.getComponentEnabledSetting(a) == PackageManager.COMPONENT_ENABLED_STATE_DISABLED; val cmd = if (h) "pm enable ${c.packageName}/${c.packageName}.MainActivityAlias" else "pm disable-user --user 0 ${c.packageName}/${c.packageName}.MainActivityAlias"; ProcessBuilder("su", "-c", cmd).start().waitFor() } catch (e: Exception) {} }.start() } } }
EOF

cat > app/src/main/java/com/example/shtile/MainActivity.kt << 'EOF'
package com.example.shtile; import android.content.Context; import android.content.Intent; import android.net.Uri; import android.os.Bundle; import android.os.Handler; import android.os.Looper; import android.text.Editable; import android.text.TextWatcher; import android.widget.*; import androidx.appcompat.app.AlertDialog; import androidx.appcompat.app.AppCompatActivity; class MainActivity : AppCompatActivity() { override fun onCreate(s: Bundle?) { super.onCreate(s); setContentView(R.layout.activity_main); val p = getSharedPreferences("GucciPrefs", Context.MODE_PRIVATE); val st = findViewById<TextView>(R.id.status); val ki = findViewById<EditText>(R.id.keyInput); val bi = findViewById<EditText>(R.id.brutalInput); val dn = findViewById<TextView>(R.id.driverNameText); val title = findViewById<TextView>(R.id.titleText); val sub = findViewById<TextView>(R.id.subtitleText); val ca = findViewById<TextView>(R.id.contactAdminText); fun chk() { Thread { val r = try { val pr = ProcessBuilder("su", "-c", "id").start(); pr.inputStream.bufferedReader().readText().contains("uid=0") } catch (e: Exception) { false }; Handler(Looper.getMainLooper()).post { if (!r) { AlertDialog.Builder(this).setTitle("ROOT REQUIRED").setMessage("INX-LOADER requires root. Please grant access.").setPositiveButton("GRANT") { _, _ -> chk() }.setNegativeButton("EXIT") { _, _ -> finish() }.setCancelable(false).show() } else { Installer.installAll(this) } } }.start() }; chk(); val tg = { try { startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://t.me/Gucci8240"))) } catch (e: Exception) { Toast.makeText(this, "Telegram not installed", Toast.LENGTH_SHORT).show() } }; title.setOnClickListener { tg() }; sub.setOnClickListener { tg() }; ca.setOnClickListener { tg() }; ki.setText(p.getString("license_key", "")); bi.setText(p.getString("brutal_option", "7")); val m = mapOf("1" to "QX1", "2" to "GT", "3" to "rt-dev", "4" to "rt-proc", "5" to "QX(2)", "6" to "KPM", "7" to "DitPro KPM", "8" to "KMA KPM", "9" to "LDK KPM", "10" to "Paradise"); bi.addTextChangedListener(object : TextWatcher { override fun beforeTextChanged(s: CharSequence?, st: Int, c: Int, a: Int) {}; override fun onTextChanged(s: CharSequence?, st: Int, b: Int, c: Int) { dn.text = m[s.toString().trim()] ?: "Unknown" }; override fun afterTextChanged(s: Editable?) {} }); dn.text = m[bi.text.toString()] ?: "Unknown"; findViewById<Button>(R.id.saveKeyBtn).setOnClickListener { p.edit().putString("license_key", ki.text.toString().trim()).putString("brutal_option", bi.text.toString().trim()).apply(); st.text = "System Configured" }; findViewById<Button>(R.id.loadFilesBtn).setOnClickListener { st.text = "Installing..."; Installer.installAll(this) { ok -> st.text = if (ok) "Files Loaded" else "Failed. Check root." } } } }
EOF

gradle assembleDebug --stacktrace
